// === Tab: mySketch ===
var W = 169;
var H = 169;
var state = new Int8Array(W*H);

var ant_x = 85;
var ant_y = 85;
var ant_dir = 0;
var ant_state = 0;

var cellSize = 4;

var speed = 7;
var accummulation = 5;

function setup() {
  createCanvas(800,800);

  for(let i=0; i<W*H; i++){
	  state[i]=0;
  }
}

function colorMap(v){
	let val = (1-v)*100+130;
	return [val,val,val];
}

function update(){
	let i = ant_x + ant_y * W;

	ant_state += state[i]*2-1;
	if(abs(ant_state)>accummulation){
		ant_dir += Math.sign(ant_state);
		ant_state = 0;
	}
	ant_dir = (ant_dir+4)%4;

	state[i] = 1-state[i];

	ant_y += ((ant_dir+1)%2)*(ant_dir-1);
	ant_x += ((ant_dir)%2)*(2-ant_dir);
	ant_y = (ant_y+H)%H;
	ant_x = (ant_x+W)%W;
}

function draw() {
  background(250);
  noStroke();
  for(let i=0; i<W*H; i++){
	  fill(colorMap(state[i]));
	  let i_x = i%W;
	  let i_y = floor(i/W);
	  rect((i_x-W/2)*cellSize + width/2, (i_y-H/2)*cellSize + height/2, cellSize, cellSize);
  }
  fill('#20e050');
  ellipse((ant_x-W/2+0.5)*cellSize + width/2, (ant_y-H/2+0.5)*cellSize + height/2, cellSize*1.6);

  for(let i=0; i<speed; i++)
  update();
}
